const SEA_TYPES={fish:{name:'물고기',coins:3,energy:2},crab:{name:'꽃게',coins:5,energy:3},shrimp:{name:'새우',coins:4,energy:2},dolphin:{name:'돌고래',coins:12,energy:7},shark:{name:'상어',coins:-8,energy:-5},item:{name:'바다 보물',coins:8,energy:4}};
const SEA_SIZE={width:900,height:520};
function seaType(roll){return roll<.41?'fish':roll<.64?'crab':roll<.83?'shrimp':roll<.91?'dolphin':roll<.99?'shark':'item';}
function newSnorkel(rng=Math.random){const state={x:450,y:290,facing:1,time:0,nextSpawn:1.8,nextId:0,targets:[],rng,catches:0,coins:0,energy:0,items:0,lostCoins:0,lostEnergy:0,invulnerableUntil:0,paused:false};for(const type of ['fish','crab','shrimp','fish','fish'])spawnSeaTarget(state,type);return state;}
function spawnSeaTarget(state,type=seaType(state.rng())){if(state.targets.length>=10)return null;const target={id:state.nextId++,type,x:55+state.rng()*790,y:65+state.rng()*385,age:0,life:type==='item'?14:7+state.rng()*5,phase:state.rng()*Math.PI*2,variant:Math.floor(state.rng()*3),caught:false};if(type==='shark'&&Math.hypot(target.x-state.x,target.y-state.y)<220)target.x=state.x<450?820:80;state.targets.push(target);return target;}
function moveSnorkeler(state,dx,dy,dt){const length=Math.hypot(dx,dy);if(!length)return;if(dx)state.facing=dx>0?1:-1;state.x=clamp(state.x+dx/length*185*dt,30,870);state.y=clamp(state.y+dy/length*185*dt,42,478);}
function seaPosition(target){if(target.type==='shark')return {x:target.x,y:target.y};return {x:target.x+Math.sin(target.age*.9+target.phase)*(target.type==='dolphin'?32:14),y:target.y+Math.sin(target.age*1.3+target.phase)*8};}
function catchSeaTarget(player,target,rng=Math.random){if(target.type==='shark'||target.caught||target.age>=target.life||!SEA_TYPES[target.type])return null;target.caught=true;const kind=SEA_TYPES[target.type];let coins=kind.coins,item=null,allOwned=false;if(target.type==='item'){const pool=ITEMS.filter(i=>!player.owned.includes(i.id));if(pool.length){item=pool[Math.min(pool.length-1,Math.floor(rng()*pool.length))];acquireItem(player,item.id);}else{coins=25;allOwned=true;}}const energy=Math.min(100-player.energy,kind.energy);coins=Math.min(1e9-player.coins,coins);player.coins+=coins;player.energy+=energy;return {name:kind.name,coins,energy,item,allOwned};}
function hitSeaShark(player,target,state){if(target.type!=='shark'||target.caught||target.age>=target.life||state.time<state.invulnerableUntil)return null;target.caught=true;const coins=Math.min(8,player.coins),energy=Math.min(5,player.energy);player.coins-=coins;player.energy-=energy;state.invulnerableUntil=state.time+2.5;state.lostCoins+=coins;state.lostEnergy+=energy;return {name:'상어',hit:true,coins:-coins,energy:-energy,item:null};}
function stepSnorkel(state,dt,keys,player){if(state.paused)return [];dt=clamp(dt,0,.05);state.time+=dt;moveSnorkeler(state,Number(keys.has('ArrowRight'))-Number(keys.has('ArrowLeft')),Number(keys.has('ArrowDown'))-Number(keys.has('ArrowUp')),dt);for(const target of state.targets){target.age+=dt;if(target.type==='shark'){const dx=state.x-target.x,dy=state.y-target.y,d=Math.hypot(dx,dy);if(d){const step=Math.min(d,110*dt);target.x+=dx/d*step;target.y+=dy/d*step;}}}state.targets=state.targets.filter(t=>!t.caught&&t.age<t.life);if(state.time>=state.nextSpawn){spawnSeaTarget(state);state.nextSpawn=state.time+1.6+state.rng();}const rewards=[];for(const target of state.targets){const pos=seaPosition(target);if(Math.hypot(state.x-pos.x,state.y-pos.y)<=40){const result=target.type==='shark'?hitSeaShark(player,target,state):catchSeaTarget(player,target,state.rng);if(result?.hit){rewards.push(result);continue;}if(result){state.catches++;state.coins+=result.coins;state.energy+=result.energy;if(result.item)state.items++;rewards.push(result);}}}state.targets=state.targets.filter(t=>!t.caught);return rewards;}

function seaArt(type,variant=0){const colors=['#f7ce76','#ef9eab','#9bb4e5'];const body=type==='shark'?'<path d="M9 46q22-25 48-13l4-25 15 30 18 15-21 5q-24 22-47-1L7 73l5-22L3 35z" fill="#637d96"/><path d="M33 53q22 17 45 0" stroke="#d3e3df" stroke-width="10" fill="none"/><path d="m53 56 9 17 10-17" fill="#516d8a"/><path d="m67 37 9 4" stroke="#263e54" stroke-width="3"/><circle cx="71" cy="44" r="3" fill="#233d53"/><path d="m69 53 5 4 4-5" fill="white"/>':type==='fish'?`<path d="m26 43-20-19v39l20-13" fill="${colors[variant]}"/><ellipse cx="53" cy="43" rx="32" ry="22" fill="${colors[variant]}"/><path d="m42 24 12-12 8 16M43 63l12 12 9-17" fill="#fff5c4"/><path d="M43 27q-10 15 0 32" stroke="#fff9e7" stroke-width="7" fill="none"/><circle cx="69" cy="37" r="4" fill="#385c68"/><path d="M73 49q-6 6-12 0" fill="none" stroke="#8c6b65" stroke-width="2"/>`:type==='crab'?'<g stroke="#d77f70" stroke-width="5" fill="none" stroke-linecap="round"><path d="m28 49-16-9m18 17L12 61m22 2-15 12m52-26 17-9M70 57l18 4M66 63l15 12M30 42 20 24m50 18 10-18"/></g><ellipse cx="50" cy="50" rx="27" ry="21" fill="#efaa8e"/><path d="M39 34V22m22 12V22" stroke="#efaa8e" stroke-width="7"/><circle cx="39" cy="21" r="4" fill="#426571"/><circle cx="61" cy="21" r="4" fill="#426571"/><path d="M12 10v13h15V10l-8 6zM72 10v13h15V10l-8 6z" fill="#e9917c"/><path d="M43 56q7 7 14 0" stroke="#b87970" fill="none" stroke-width="3"/>':type==='shrimp'?'<path d="M28 63q-26-40 18-43 33-2 31 27-2 28-33 26" stroke="#edae9d" stroke-width="20" fill="none" stroke-linecap="round"/><path d="m41 19 5 12m14-9-1 13m15 1-12 4m12 13-12-3M60 64l-5-12" stroke="#fff0dd" stroke-width="3"/><path d="m27 47 4-31M29 48 13 26m35 41-6 18m17-20-5 19" stroke="#d89788" stroke-width="2" fill="none"/><path d="m45 65-16-8 3 20z" fill="#e39389"/><circle cx="32" cy="42" r="4" fill="#47656a"/>':type==='dolphin'?'<path d="M11 40q16-28 48-15l8-16 5 25q14 6 23 15l-24 1q-15 20-39 10l-20 16 1-21L4 48z" fill="#8fbfd7"/><path d="M28 50q21 17 45-2" stroke="#d9f1ec" stroke-width="9" fill="none"/><path d="m45 51 7 22 11-18" fill="#7eaec8"/><circle cx="69" cy="38" r="3" fill="#355975"/>':'<path d="m13 35 15-20h48l13 20v40H13z" fill="#d3a275"/><rect x="13" y="38" width="76" height="36" rx="6" fill="#edca86"/><path d="M13 39h76M35 18v56m32-56v56" stroke="#fff0b5" stroke-width="5"/><rect x="43" y="43" width="17" height="16" rx="3" fill="#8eaa9a"/><path d="m49 0 4 8 9 3-9 3-4 8-3-8-9-3 9-3z" fill="#fff8c5"/>';
return `<svg viewBox="0 0 100 90" aria-hidden="true">${body}</svg>`;}

// ---- app.js ----
const app=document.querySelector('#app');
let activeSlot=0, pendingSlot=0, slotMode='load', shopFilter='all', shopPage=0;
let loaded=load(), player=null, page='welcome', race=null, audio=null, muted=false, raf=0, chosen=0;
function load(){try{return readSave(localStorage,activeSlot);}catch{return {player:null,error:'이 브라우저에서는 저장소를 사용할 수 없어요.'};}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>({home:'⌂',village:'✳',practice:'≈',stadium:'⚑',beach:'☀',shop:'◇',save:'↓',coin:'●'}[name]||'✦');
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function save(manual=false){if(!player)return;let ok=false;try{ok=savePlayer(localStorage,player,activeSlot);}catch{}if(!ok)toast('저장하지 못했어요. 브라우저 저장 권한을 확인해 주세요.');else if(manual)toast('저장 완료! 다음에도 여기서 이어갈 수 있어요.');return ok;}
function header(){return `<header class="topbar"><a class="brand" href="#" data-go="${player?'village':'welcome'}"><span class="brand-mark">≈</span> 첨벙클럽<span class="brand-en">SPLASH CLUB</span></a><div class="top-right"><a class="project-home" href="../" aria-label="프로젝트 홈 게임 목록으로 돌아가기"><span aria-hidden="true">⌂</span> 홈으로</a><span class="local-tag"><i></i> 나만의 수영 라이프</span><button class="icon-btn" data-action="sound" aria-label="소리 켜기 또는 끄기">${(player?.settings.sound??!muted)?'♫':'♪'}</button><button class="icon-btn" data-action="settings" aria-label="설정">⚙</button></div></header>`;}
function sidebar(){const s=stats(player);return `<aside class="sidebar"><div class="profile"><div class="avatar-disc">${swimmer(player.color,false,'profile',player.equipped)}</div><span class="pill">Lv. ${player.level} · ${player.level<3?'새싹 수영인':player.level<6?'열정 수영인':'프로 수영인'}</span><h2>${esc(player.name)} <small>선수</small></h2><div class="xp-label"><span>다음 레벨까지</span><b>${player.level===20?'MAX':`${player.xp} / ${needXP(player.level)} XP`}</b></div><div class="progress"><span style="width:${player.level===20?100:player.xp/needXP(player.level)*100}%"></span></div></div><nav>${[['village','수영 마을'],['home','우리 집'],['shop','상점'],['practice','수영연습장'],['stadium','수영경기장'],['beach','해변']].map(([p,n])=>`<button class="nav-item ${page===p?'active':''}" data-go="${p}"><span>${icon(p)}</span>${n}${page===p?'<b>•</b>':''}</button>`).join('')}</nav><div class="sidebar-stats"><div class="section-eyebrow">MY ABILITY</div><div><span>기본 속도</span><b>${s.base.toFixed(2)} <small>m/s</small></b></div><div><span>추진력</span><b>${Math.round(s.power*100)}</b></div><div><span>안정성</span><b>${Math.round(s.stability*100)}</b></div></div><div class="save-note"><i></i> 슬롯 ${activeSlot+1} · ${player.day}일째 · ${player.savedAt?'자동 저장 중':'미저장'}<small>이 브라우저에 안전하게 보관해요.</small></div></aside>`;}
function shell(content){app.innerHTML=header()+`<div class="layout">${sidebar()}<main>${content}</main></div><footer>첨벙클럽 <span>조금씩, 나만의 속도로.</span><span>${page==='beach'?'↑ ↓ ← → &nbsp; 물결 따라 자유롭게':'Q · W · O · P &nbsp; 리듬을 타고 앞으로'}</span></footer>`;}
function title(eyebrow,h,sub){return `<div class="page-title"><div><div class="section-eyebrow">${eyebrow}</div><h1>${h}</h1><p>${sub}</p></div><div class="wallet"><span>●</span> ${player.coins.toLocaleString()} <small>코인</small></div></div>`;}
function building(type){if(type==='beach')return `<svg viewBox="0 0 280 180" aria-hidden="true"><rect x="15" y="35" width="250" height="126" rx="28" fill="#bbe5e4"/><path d="M15 120q45-40 93 0t157 0v40H15z" fill="#f4dfb3"/><path d="M70 139V65" stroke="#a4846d" stroke-width="6"/><path d="M32 70q38-65 76 0z" fill="#efa99d"/><circle cx="210" cy="52" r="20" fill="#fff0bb"/><path d="M145 99q20-24 42 0l18-10v23l-18-10q-20 23-42-3" fill="#8eb4cd"/></svg>`;if(type==='shop')return `<svg viewBox="0 0 280 180" aria-hidden="true"><ellipse cx="140" cy="158" rx="99" ry="10" fill="#dfccde"/><rect x="64" y="67" width="152" height="86" rx="8" fill="#fff7e5"/><path d="M54 67 L70 40 H210 L226 67Z" fill="#ed9db8"/><path d="M54 67 H226 V81 Q212 97 198 81 Q184 97 170 81 Q156 97 142 81 Q128 97 114 81 Q100 97 86 81 Q70 97 54 81Z" fill="#f5bad0"/><rect x="79" y="101" width="66" height="35" rx="6" fill="#bee5e5"/><rect x="162" y="97" width="37" height="56" rx="8" fill="#acbfda"/><circle cx="190" cy="126" r="3" fill="#fff"/><rect x="101" y="18" width="78" height="30" rx="10" fill="#fff"/><text x="140" y="39" text-anchor="middle" fill="#965f83" font-size="18">SHOP</text><path d="M86 116 Q112 102 138 116" stroke="#fff" stroke-width="4" fill="none"/></svg>`;if(type==='home')return `<svg viewBox="0 0 280 180"><ellipse cx="140" cy="155" rx="100" ry="12" fill="#d9ccb5" opacity=".4"/><path d="M58 83 L140 27 221 83" stroke="#ce795e" stroke-width="21" stroke-linejoin="round" fill="#ebac89"/><rect x="74" y="82" width="132" height="69" rx="5" fill="#fff5da"/><rect x="125" y="106" width="31" height="45" rx="13" fill="#90b8a8"/><rect x="90" y="97" width="25" height="25" rx="5" fill="#a7d7df"/><rect x="167" y="97" width="25" height="25" rx="5" fill="#a7d7df"/><path d="M102 97 V122 M90 109 H115 M180 97 V122 M167 109 H192" stroke="white" stroke-width="3"/><path d="M186 53 V28 H202 V67" fill="#cf8067"/><path d="M45 143 V112 M233 146 V112" stroke="#879d6b" stroke-width="6"/><circle cx="44" cy="110" r="20" fill="#a8bf89"/><circle cx="234" cy="111" r="18" fill="#afc595"/><path d="M121 153 H160 L178 175 H101Z" fill="#e4d6bd"/></svg>`;return `<svg viewBox="0 0 280 180"><ellipse cx="140" cy="158" rx="108" ry="10" fill="#7abfc322"/><path d="M38 74 L90 40 H235 V126 L185 158 H38Z" fill="${type==='practice'?'#d6edef':'#d8dfea'}"/><path d="M49 85 L96 55 H221 L175 86Z" fill="#fcffff"/><path d="M49 88 H175 V147 H49Z" fill="#71c5d4"/><path d="M60 95 H163 V137 H60Z" fill="#9de1e7"/><path d="M65 106 H160 M65 121 H160" stroke="#fff" stroke-width="3" stroke-dasharray="7 5"/><path d="M183 87 L221 62 V118 L183 144Z" fill="#b0cbd6"/><path d="M71 84 V68 Q71 58 78 58 V77 M87 84 V65" fill="none" stroke="#7697a6" stroke-width="4"/>${type==='stadium'?'<path d="M103 38 V12 H160 L148 24 160 35 H103" fill="#f2bc56"/><text x="114" y="30" font-size="15" fill="white">★</text><rect x="194" y="91" width="19" height="15" rx="2" fill="#f7d073"/>':'<circle cx="214" cy="38" r="16" fill="#f4d37d"/><path d="M32 55 Q49 43 66 55" stroke="white" stroke-width="5" fill="none"/>'}</svg>`;}
function welcome(){app.innerHTML=header()+`<main class="welcome"><div class="welcome-copy"><div class="section-eyebrow">YOUR LITTLE SWIMMING STORY</div><h1>오늘도,<br>기분 좋게 <em>첨벙!</em></h1><p>물살을 가르는 작은 리듬.<br>나만의 선수와 함께 수영 이야기를 시작해요.</p><div class="welcome-actions"><button class="primary" data-action="continue" >이어서 하기 <span>→</span></button><button class="secondary" data-action="new">새로 하기 <span>＋</span></button></div><p class="save-description">10개의 슬롯에 나만의 수영 이야기를 보관해요.<br>이어서 하기에서 원하는 슬롯을 골라 주세요.</p><div class="welcome-features"><span>♫ 리듬으로 수영하고</span><span>↗ 매일 성장하고</span><span>⚑ 함께 겨뤄요</span></div></div><div class="welcome-art"><div class="pool-art"><span class="pool-word">SPLASH<br>CLUB.</span><div class="hero-swimmer">${swimmer(0,true)}</div><div class="mini-swimmer">${swimmer(1,true)}</div><span class="float-tag">✦ 나의 첫 번째 레인</span></div><div class="art-caption">A LITTLE RHYTHM. A LITTLE GROWTH.</div></div></main><footer>첨벙클럽<span>PC 키보드 플레이 · 저장은 현재 브라우저에 보관됩니다</span></footer>`;}
function village(){shell(title('THE SWIMMING VILLAGE','오늘은 어디로 가볼까요?',`${esc(player.name)} 선수, 반가워요. 작은 연습이 멋진 기록이 되는 곳.`)+`<section class="village-banner"><div><span class="pill white">MY SWIMMING DAYS</span><h2>서두르지 않아도 괜찮아.<br>한 박자씩, 더 멀리.</h2><p>연습하고, 성장하고, 나만의 레이스를 즐겨요.</p><button class="dark-btn" data-go="practice">오늘의 연습 시작하기 <span>↗</span></button></div><div class="banner-art"><span class="orbit one"></span><span class="orbit two"></span>${swimmer(player.color,false,'hero',player.equipped)}<span class="bubble b1">✦</span><span class="bubble b2">≈</span><div class="floating-note">READY TO SPLASH!</div></div></section><div class="section-heading"><h2>우리 동네 둘러보기</h2><span>가고 싶은 장소를 선택하세요</span></div><section class="destination-grid">${[['home','01','우리 집','잠깐 쉬어가며 다음 수영을 준비해요.','저장 · 생활 활동','집으로 가기'],['shop','02','상점','알록달록 장비로 다음 수영을 준비해요.','100종 장비 · 구매와 장착','상점으로 가기'],['practice','03','수영연습장','혼자서 차근차근, 리듬을 익혀봐요.','1인 연습 · 경험치 획득','연습하러 가기'],['stadium','04','수영경기장','다섯 개의 레인, 두근거리는 출발!','5인 레이스 · 순위 보상','경기하러 가기'],['beach','05','해변','물결 아래 친구들과 보물을 찾아요.','스노클링 · 코인과 활력','해변으로 가기']].map(([p,n,h,d,t,b])=>`<article class="destination ${p}"><div class="destination-art"><span class="place-number">${n} /</span>${building(p)}</div><div class="destination-copy"><span class="place-tag">${t}</span><h3>${h}</h3><p>${d}</p><button data-go="${p}">${b}<span>↗</span></button></div></article>`).join('')}</section><section class="tip-strip"><span class="tip-icon">♫</span><div><b>오늘의 수영 팁</b><p>Q·W는 왼쪽, O·P는 오른쪽! 리듬을 이어가면 콤보와 함께 속도도 올라가요.</p></div><span class="key-group"><kbd>Q</kbd><kbd>W</kbd><kbd>O</kbd><kbd>P</kbd></span></section>`);}

